import { StagehandCrawler } from '@crawlee/stagehand';
import { z } from 'zod';

const crawler = new StagehandCrawler({
  stagehandOptions: {
    env: 'LOCAL',
    model: 'openai/gpt-4.1-mini',
  },
  async requestHandler({ page, request, log }) {
    log.info(`Processing ${request.url}`);

    // Use natural language to interact
    await page.act('Click the Products link');

    // Extract structured data
    const products = await page.extract(
      'Get all products',
      z.object({
        items: z.array(z.object({
          name: z.string(),
          price: z.number(),
        })),
      })
    );

    await Dataset.pushData(products);
  },
});

await crawler.run(['https://example.com']);
```

```typescript
import { StagehandCrawler } from '@crawlee/stagehand';
import { z } from 'zod';

const crawler = new StagehandCrawler({
  stagehandOptions: {
    env: 'LOCAL',
    model: 'openai/gpt-4.1-mini',
    verbose: 1,
  },
  maxConcurrency: 3,
  async requestHandler({ page, request, log }) {
    log.info(`Crawling ${request.url}`);

    // Use AI to interact with the page
    await page.act('Click the Products link');
    await page.act('Scroll to load more items');

    // Extract structured data
    const products = await page.extract(
      'Get all product names and prices',
      z.object({
        items: z.array(z.object({
          name: z.string(),
          price: z.number(),
        })),
      })
    );

    log.info(`Found ${products.items.length} products`);
  },
});

await crawler.run(['https://example.com']);
```

